ect:focus{outline:2px solid #8cced2;border-color:#00818b}.result{margin-top:24px;padding:23px 19px;background:#007f8b;color:#fff;border-radius:20px;box-shadow:0 9px 22px #007f8b29}.result-heading{display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:12px;font-weight:850;letter-spacing:.7px}.result-check{display:grid;place-items:center;border:1px solid #ffffff80;border-radius:50%;height:27px;width:27px}.net-line{display:flex;align-items:baseline;gap:8px;margin:19px 0 8px;min-width:0}.net-line strong{font-size:clamp(55px,12vw,80px);line-height:1;font-variant-numeric:tabular-nums;letter-spacing:-2px;}.net-line span{font-size:22px;font-weight:800}.result-subtitle{font-size:12px;color:#e0f6f8;margin:13px 0 17px}.copy-btn{width:100%;background:#fff;border:0;color:#007985;border-radius:30px;padding:15px;font-weight:850;font-size:15px;cursor:pointer}.copy-btn:disabled{opacity:.65}.details{margin-top:16px;border:1px solid #e5e5e5;border-radius:14px;overflow:hidden}.details>div{display:flex;justify-content:space-between;gap:10px;padding:14px;font-size:13px}.details>div+div{border-top:1px solid #eee}.details span,.muted{color:#707177}.details strong{font-variant-numeric:tabular-nums}.muted{font-size:13px;line-height:1.55}.reset-btn{display:block;border:0;background:none;color:#007b85;font-weight:800;margin:20px auto 0;cursor:pointer}.error{color:#b50019;font-size:12px;font-weight:700}.count{background:#e1f2f3;color:#007b85;border-radius:99px;padding:8px 10px;font-size:11px;font-weight:800;white-space:nowrap}.basket-list{margin:17px 0}.basket-item{display:flex;align-items:center;gap:8px;border:1px solid #e4e5e8;border-radius:13px;padding:10px 8px;margin-bottom:9px;background:#fff;}.basket-item.dragging{opacity:.5}.basket-item.drag-over{outline:2px dashed #007f8b}.drag-handle{border:0;background:#e3f2f3;color:#007d87;border-radius:9px;padding:10px 8px;font-size:22px;cursor:grab;touch-action:none;user-select:none}.basket-info{flex:1;min-width:0}.basket-info strong{display:block;font-size:13px;overflow-wrap:anywhere}.basket-info span{display:block;color:#777;font-size:11px;margin-top:4px}.item-actions{display:flex;gap:4px;align-items:center}.small-action{border:0;background:#f1f2f3;border-radius:8px;padding:9px 7px;font-size:11px;font-weight:750;cursor:pointer}.small-action.delete{color:#c51b28}.move-actions{display:flex;flex-direction:column;gap:3px}.move-actions button{border:0;border-radius:6px;background:#e3f2f3;color:#007985;font-size:11px;padding:3px 6px;cursor:pointer}.move-actions button:disabled{opacity:.3}.basket-form{border-top:1px solid #ededed;padding-top:17px}.basket-form h3{font-size:16px;margin:0 0 8px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.form-buttons{display:flex;gap:8px;flex-wrap:wrap;margin-top:15px}.primary-btn{border:0;background:#007f8b;color:#fff;border-radius:28px;padding:14px 18px;font-size:13px;font-weight:800;cursor:pointer}.ghost-btn{border:0;background:#ededf0;border-radius:25px;padding:13px;font-weight:750;cursor:pointer}.hidden{display:none!important}.backup-buttons{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-top:16px}.outline-btn{display:flex;align-items:center;justify-content:center;text-align:center;border:1.5px solid #007f8b;color:#007985;background:#fff;border-radius:25px;padding:13px 8px;font-size:12px;font-weight:800;cursor:pointer}.status{color:#666;font-size:12px}.empty{background:#f8f8f8;border-radius:12px;padding:20px;color:#888;text-align:center;font-size:13px}footer{text-align:center;color:#777;font-size:11px;padding:15px 20px}@media(max-width:380px){.card{padding:17px 12px}.form-grid{grid-template-columns:1fr}.small-action{padding:8px 5px}.basket-item{gap:5px}.net-line strong{font-size:51px}}

/* V5 : titre et gestes tactiles optimisés */
html{-webkit-text-size-adjust:100%;scroll-behavior:auto}body{overscroll-behavior-y:auto;-webkit-tap-highlight-color:transparent}button,input,select{font-family:inherit}button{transition:background-color .16s ease,opacity .16s ease,transform .16s ease}button:active:not(:disabled){transform:scale(.98)}.brand h1{font-size:clamp(18px,4.9vw,27px);font-weight:950;letter-spacing:-.55px;line-height:1.08}.basket-item,.basket-item *{-webkit-user-select:none;user-select:none;-webkit-touch-callout:none}.basket-item{touch-action:pan-y;cursor:grab;position:relative;transition:background-color .16s ease,border-color .16s ease;will-change:auto}.basket-item.is-placeholder{opacity:.24;border:2px dashed #007f8b;background:#e1f2f3}.basket-item.drag-over{outline:0;border-color:#007f8b}.basket-item.dragging{opacity:.35}.drag-handle{width:38px;height:40px;flex:0 0 38px;display:grid;place-items:center;padding:0;line-height:1;touch-action:pan-y}.drag-handle svg{width:20px;height:20px;display:block}.drag-ghost{position:fixed!important;z-index:9999!important;pointer-events:none!important;margin:0!important;box-shadow:0 14px 34px #002c3540!important;border:2px solid #007f8b!important;background:#fff!important;opacity:.98!important;transform:translate3d(0,0,0);will-change:transform;transition:none!important}.drag-ghost *{pointer-events:none!important}.basket-list.is-reordering{touch-action:none}.basket-list.is-reordering .basket-item:not(.drag-ghost){transition:transform .15s ease,background-color .15s ease}.card{contain:layout style}.result{transform:translateZ(0)}@media(prefers-reduced-motion:reduce){button,.basket-item,.basket-list.is-reordering .basket-item{transition:none!important}}

/* Titre renforcé */
.brand h1{font-weight:900!important;letter-spacing:-.5px;}

/* V7 : sélection en premier, résultat rapproché et historique */
.calc-card .weight-field{margin-bottom:0}.calc-card .result{margin-top:15px}.weigh-actions{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-top:15px}.weigh-actions button{min-height:48px;border-radius:24px;font-size:13px;font-weight:800}.save-weigh{padding:12px 8px}.save-weigh:disabled{opacity:.45}.weigh-status{min-height:1em;font-size:12px;font-weight:750;color:#007985;margin:9px 0 0}.history-list{display:grid;gap:8px;margin-top:13px}.history-item{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:13px;border:1px solid #e4e7e9;border-radius:13px}.history-info{display:grid;gap:3px;}.history-info strong{font-size:13px}.history-info span{font-size:11px;color:#74767a}.history-net{color:#007985;font-size:19px;white-space:nowrap;font-variant-numeric:tabular-nums}.history-clear{display:block;margin:15px 0 0 auto;border:0;background:transparent;color:#a42a35;font-size:12px;font-weight:750;cursor:pointer}.result-confirmed{animation:weigh-confirm .8s ease-out}@keyframes weigh-confirm{0%{box-shadow:0 0 0 0 #00a99d80;transform:scale(1)}35%{box-shadow:0 0 0 7px #00a99d26;transform:scale(1.015)}100%{box-shadow:0 9px 22px #007f8b29;transform:scale(1)}}@media(prefers-reduced-motion:reduce){.result-confirmed{animation:none;outline:3px solid #a1e9dc}}@media(max-width:360px){.weigh-actions{grid-template-columns:1fr}}

/* V8 : typographie renforcée des deux titres uniquement */
.brand h1{font-weight:950!important;letter-spacing:-.65px;}

/* V9 — saisie et historique */
.weight-row{display:flex;gap:9px;align-items:stretch}.weight-row .weight-field{flex:1;min-width:0}.weight-row .weight-field input{padding:13px 12px;font-size:clamp(23px,6.5vw,30px)}.weight-row .weight-field span{padding-right:12px}.new-weigh-btn{display:flex;flex:0 0 105px;align-items:center;justify-content:center;gap:5px;border:1px solid #b4dfe1;border-radius:17px;background:#e2f2f3;color:#007985;font-weight:850;font-size:19px;line-height:1.15;cursor:pointer}.new-weigh-btn span{font-size:12px}.history-toggle{display:block;width:100%;margin:10px 0;padding:12px 10px;border:1px solid #b4dfe1;border-radius:24px;background:#e2f2f3;color:#007985;font-size:13px;font-weight:800;cursor:pointer}.history-toggle[hidden]{display:none}.weigh-status:empty{display:none}@media(max-width:380px){.new-weigh-btn{flex-basis:88px}.new-weigh-btn span{font-size:11px}}

/* V10 — titres visiblement plus épais, sans police externe. */
.brand h1{font-family:Arial,Helvetica,sans-serif;font-weight:900!important;-webkit-text-stroke:.65px currentColor;letter-spacing:-.75px;text-rendering:geometricPrecision}
.intro h2,.intro h2 em{font-family:Arial,Helvetica,sans-serif;font-weight:900!important;-webkit-text-stroke:1.05px currentColor;letter-spacing:-1.15px;text-rendering:geometricPrecision}
/* Une seule commande, avec chevron animé et état accessible. */
.history-toggle{display:flex;align-items:center;justify-content:center;gap:9px}
.history-chevron{width:19px;height:19px;flex:none;fill:none;stroke:currentColor;stroke-width:2.7;stroke-linecap:round;stroke-linejoin:round;transition:transform .24s cubic-bezier(.2,.75,.25,1)}
.history-toggle[aria-expanded="true"] .history-chevron{transform:rotate(180deg)}
@media(prefers-reduced-motion:reduce){.history-chevron{transition:none}}

/* V11 — exemple de saisie plus discret et prévention du double-tap zoom */
.weight-field input::placeholder{color:#b3b8bf;opacity:1;font-weight:500;}
.weight-field input::-webkit-input-placeholder{color:#b3b8bf;font-weight:500;}
html,body{touch-action:pan-y;}
button,select,input,.weight-field{touch-action:manipulation;}

/* V14 : exemple discret mais gras, sans halo bleu de focus sur le poids */
.weight-field input::placeholder{color:#c6cbd0;opacity:1;font-weight:800}
.weight-field input::-webkit-input-placeholder{opacity:1;}
.weight-field input:focus,.weight-field input:focus-visible{outline:none!important;box-shadow:none!important;border:0!important;-webkit-appearance:none;appearance:none}
.weight-field:focus-within{outline:none;box-shadow:none}

/* V21 — notification Liquid Glass peaufinée. */
.offline-indicator[hidden]{display:none!important}
.offline-indicator{z-index:1000;
  top:calc(env(safe-area-inset-top, 0px) + 12px);width:min(calc(100% - 28px),440px);gap:12px;
  padding:12px 13px 12px 14px;
  border-radius:30px;
  border:1px solid rgba(255,255,255,.37);
  background:linear-gradient(150deg,rgba(255,255,255,.19),rgba(90,110,117,.20) 58%,rgba(255,255,255,.13));
  -webkit-backdrop-filter:blur(22px) saturate(155%) brightness(.91);
  backdrop-filter:blur(22px) saturate(155%) brightness(.91);
  box-shadow:0 10px 30px rgba(13,29,36,.19),inset 0 1.5px 0 rgba(255,255,255,.62),inset 0 -1px 0 rgba(255,255,255,.13);
  color:#142d33;transform-origin:50% 0;
}
.offline-indicator::before{inset:1px;border-radius:inherit;z-index:-1;background:linear-gradient(125deg,rgba(255,255,255,.25),transparent 34%,transparent 70%,rgba(255,255,255,.12));}
.offline-symbol{flex:0 0 42px;width:42px;height:42px;background:rgba(255,255,255,.20);border:1px solid rgba(255,255,255,.29);overflow:hidden}
.offline-symbol img{display:block;width:20px;height:20px;opacity:.96}
.offline-copy{display:flex;flex-direction:column;gap:3px;line-height:1.25;text-shadow:0 1px 1px rgba(255,255,255,.40)}
.offline-copy strong{font-size:15px;font-weight:820;letter-spacing:-.18px;color:#102b33}
.offline-copy>span{font-size:13px;font-weight:620;color:#29464e}
.offline-dismiss{flex:0 0 30px;width:30px;height:30px;border:1px solid rgba(255,255,255,.3);border-radius:50%;background:rgba(255,255,255,.20);color:#24454d;-webkit-tap-highlight-color:transparent}
.offline-dismiss:focus-visible{outline:2px solid #007f8b;outline-offset:3px}
.offline-indicator.is-entering{animation:glass-enter .58s cubic-bezier(.22,1.15,.33,1) both}
.offline-indicator.is-leaving{animation:glass-leave .36s cubic-bezier(.4,0,.7,.3) both;}
@keyframes glass-enter{0%{opacity:0;transform:translate3d(-50%,-68px,0) scale(.90)}70%{opacity:1;transform:translate3d(-50%,5px,0) scale(1.012)}100%{opacity:1;transform:translate3d(-50%,0,0) scale(1)}}
@keyframes glass-leave{0%{opacity:1;transform:translate3d(-50%,0,0) scale(1)}100%{opacity:0;transform:translate3d(-50%,-43px,0) scale(.96)}}
@media(prefers-reduced-motion:reduce){.offline-indicator.is-entering,.offline-indicator.is-leaving{animation:none}}
@media(max-width:360px){.offline-indicator{padding:11px}.offline-symbol{flex-basis:37px;width:37px;height:37px}.offline-symbol img{width:18px;height:18px}.offline-copy strong{font-size:14px}.offline-copy>span{font-size:12px}}
@supports not ((backdrop-filter:blur(1px)) or (-webkit-backdrop-filter:blur(1px))){.offline-indicator{background:rgba(220,235,237,.94)}}

/* V22 — Ajouts compacts, sans modification du Liquid Glass V21. */
.session-card{border-color:#d5e9e9;background:linear-gradient(175deg,#fff 70%,#f6fbfb);}
.session-top,.v22-group-head{display:flex;align-items:center;justify-content:space-between;gap:10px}
.session-top h2{font-size:22px;letter-spacing:-.5px;margin:5px 0 0}
.session-pill{position:relative;display:inline-flex;align-items:center;font-size:11px;font-weight:850;border-radius:100px;padding:9px 11px;white-space:nowrap}
.session-pill.active{padding-left:33px}
.session-pill.active::before{content:'';position:absolute;left:13px;top:50%;width:10px;height:10px;border-radius:50%;transform:translateY(-50%);z-index:1}
.session-pill.active::after{content:'';position:absolute;left:8px;top:50%;width:20px;height:20px;border-radius:50%;background:rgba(32,191,99,.14);transform:translateY(-50%);animation:session-pill-pulse 1.7s ease-in-out infinite}
@keyframes session-pill-pulse{0%,100%{transform:translateY(-50%) scale(.92);opacity:.62}50%{transform:translateY(-50%) scale(1.08);opacity:1}}
.session-live{display:grid;grid-template-columns:1fr .7fr 1.15fr;gap:10px;margin:16px 0 6px}
.session-live[hidden],.session-actions [hidden],.v22-group[hidden],.v22-completed[hidden],.v22-warning[hidden],.v22-session-list [hidden]{display:none!important}
.session-live>div{display:grid;gap:6px;border:1px solid #d8ecee;background:#eff8f8;border-radius:14px;padding:14px 12px}
.session-live small,.v22-stat small,.v22-group-total small,.v22-completed small{font-size:10px;line-height:1.35;font-weight:700;color:#63747b}
.session-live strong{color:#006c77;font-size:16px;letter-spacing:-.2px;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}
.session-actions{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:18px}
.session-actions button{justify-content:center}
.session-actions .primary-btn,.session-actions .outline-btn{min-height:58px}
.v22-message{font-size:12px;font-weight:700;color:#087985;margin:10px 0 0}
.v22-message:empty{display:none}
.v22-mode{display:flex;gap:4px;border-radius:13px;padding:4px;background:#e9f0f1;margin:0 0 11px}
.mode-btn{flex:1;border:0;background:transparent;color:#47646c;padding:9px 5px;border-radius:10px;font-size:12px;font-weight:800;cursor:pointer}
.mode-btn[aria-pressed="true"]{background:#fff;color:#007780;box-shadow:0 2px 7px #143b491c}
.v22-hint{font-size:11px;color:#797e82;margin:9px 4px 0}
.v22-warning{padding:13px;background:#fff7e9;border:1px solid #efc98a;border-radius:13px;margin-top:10px;color:#88500e;font-size:12px;line-height:1.45;font-weight:750}
.warning-confirm{margin-top:9px;display:block;width:100%;border:1px solid #dcaa5b;border-radius:16px;padding:11px;background:#fff;color:#714310;font-weight:800;cursor:pointer}
.same-product-btn{margin-top:10px;width:100%;border:1px solid #ffffffa5;color:#fff;background:#ffffff23;border-radius:24px;padding:13px;font-size:13px;font-weight:850;cursor:pointer}
.same-product-btn:disabled{opacity:.48;cursor:not-allowed}
.v22-group{margin-top:13px;border-radius:18px;border:1.5px solid #b0dddf;background:#f6fcfc;padding:16px}
.v22-group-head h3{margin:6px 0 0;font-size:17px;line-height:1.3}
.v22-group-total{display:grid;gap:5px;margin-top:15px;padding:15px;background:#dff3f4;border-radius:13px;color:#006d78}
.v22-group-total strong{font-size:29px;letter-spacing:-.6px;font-variant-numeric:tabular-nums}
.v22-group-list{display:grid;gap:7px;margin:13px 0}
.v22-group-entry{display:flex;justify-content:space-between;gap:10px;align-items:center;padding:10px 0;border-bottom:1px solid #dbeded}
.v22-group-entry>div:first-child{display:grid;gap:4px;min-width:0}
.v22-group-entry strong{font-size:12px}
.v22-group-entry small{font-size:11px;color:#65767c}
.v22-group-right{display:flex;align-items:center;gap:8px;white-space:nowrap}
.v22-group-right strong{color:#007482;font-size:15px;font-variant-numeric:tabular-nums}
.v22-entry-delete{border:0;border-radius:50%;width:28px;height:28px;background:#e5e9ea;color:#8c2e38;font-size:18px;cursor:pointer}
.v22-wide{width:100%;margin-top:7px}
.v22-completed{display:flex;justify-content:space-between;gap:10px;align-items:center;border:1px solid #b1d9df;background:#f1faf9;border-radius:15px;padding:13px;margin-top:12px}
.v22-completed>div{display:grid;gap:5px}
.v22-completed strong{color:#006f7a;font-size:23px;font-variant-numeric:tabular-nums}
.v22-completed .outline-btn{flex-shrink:0;padding:11px 13px}
.v22-undo-row{margin-top:11px;display:flex;align-items:center;justify-content:space-between;gap:9px}
.v22-undo{border:0;border-radius:12px;background:#e7f4f5;color:#006f78;font-size:12px;font-weight:850;padding:10px 13px;cursor:pointer}
.v22-undo:disabled{opacity:.38;cursor:default}
.v22-undo-row .muted{font-size:11px;text-align:right}
.v22-settings{border-top:1px solid #ecedef;padding-top:11px;margin-top:10px}
.v22-settings summary{cursor:pointer;font-size:12px;font-weight:760;color:#56727a}
.v22-settings label{margin-top:12px!important}
.v22-settings input{max-width:200px}
.v22-session-list{display:grid;gap:8px}
.v22-session-item{border:1px solid #e0e7e8;border-radius:14px;padding:0 12px;overflow:hidden}
.v22-session-item summary{cursor:pointer;padding:15px 0;display:grid;gap:6px;list-style-position:inside;color:#253c44}
.v22-session-item summary::marker{color:#007e89}
.v22-session-item summary strong{font-size:14px}
.v22-session-item summary span{font-size:12px;color:#69777d;line-height:1.5}
.v22-bilan{border-top:1px solid #e3eaeb;padding:12px 0 15px}
.v22-stats-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px}
.v22-stat{display:grid;gap:6px;padding:11px;background:#f4f9f9;border-radius:10px;min-width:0}
.v22-stat strong{font-size:13px;font-weight:820;color:#075f6a;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}
.v22-bilan h4{font-size:13px;color:#263a41;margin:20px 0 10px}
.v22-stat-line{color:#586970;font-size:12px;margin:6px 2px}
.v22-bar-row{display:grid;grid-template-columns:43px minmax(0,1fr) 20px;gap:8px;align-items:center;margin:8px 0;font-size:11px;color:#526a6f}
.v22-bar-track{height:8px;background:#e5eeee;border-radius:9px;overflow:hidden}
.v22-bar-fill{height:100%;background:linear-gradient(90deg,#00818b,#48adb0);border-radius:9px}
.v22-session-export{display:flex;gap:8px;margin-top:18px}
.v22-session-export>*{flex:1}
.v22-backup-actions{display:grid;gap:9px;margin-top:12px}
.v22-backup-actions>.primary-btn{min-height:46px}
