/* États animés doux : neutre, actif, pause. */
.intro-session-dot{position:relative;flex:0 0 8px;width:8px;height:8px;background:#d6e3f1;box-shadow:none}
.intro-session-dot::after{content:"";position:absolute;inset:-5px;border-radius:50%;background:rgba(215,229,243,.22);animation:soft-session-pulse 2s ease-in-out infinite}
.intro-session-state.is-running .intro-session-dot{background:#58e3aa;box-shadow:none}
