.session-pill{padding-left:31px;background:#edf0f1;color:#5e6370}
.session-pill::before{content:"";position:absolute;left:13px;top:50%;width:9px;height:9px;border-radius:50%;background:#a9b5bd;transform:translateY(-50%);z-index:1}
.session-pill::after{content:"";position:absolute;left:8px;top:50%;width:19px;height:19px;border-radius:50%;background:rgba(169,181,189,.2);transform:translateY(-50%);animation:session-pill-pulse 1.9s ease-in-out infinite}
.session-pill.active{background:#dff5e8;color:#0b6b4f;padding-left:31px}
.session-pill.active::before{background:#20bf63;width:9px;height:9px}
.session-pill.active::after{background:rgba(32,191,99,.17);width:19px;height:19px}
