.undo-toast[hidden]{display:none!important}
.undo-toast{
 position:fixed;z-index:2000;
 left:50%;bottom:calc(17px + env(safe-area-inset-bottom,0px));
 transform:translate3d(-50%,0,0);
 width:max-content;max-width:calc(100vw - 28px);
