 box-shadow:0 12px 32px rgba(21,76,86,.17),0 2px 7px rgba(26,55,67,.07),inset 0 1px 0 rgba(255,255,255,.9);
 font-family:inherit;font-size:13px;font-weight:750;
 overflow:hidden;isolation:isolate;
}
.undo-toast-symbol{
 display:grid;place-items:center;flex:0 0 30px;
 width:30px;height:30px;border-radius:50%;
 background:#e2f4f2;color:#007f8b;
 border:1px solid #c6e7e5;
}
.undo-toast-symbol svg{width:17px;height:17px;display:block;fill:none;stroke:currentColor;stroke-width:2.5;stroke-linecap:round;stroke-linejoin:round}
.undo-toast-message{min-width:0;overflow-wrap:anywhere;line-height:1.4}
.undo-toast-button{
 flex:0 0 auto;min-height:42px;
 padding:9px 14px;border:1px solid #b9e1e4;border-radius:13px;
 background:#e2f2f3;color:#007985;
 font:inherit;font-weight:850;cursor:pointer;
 touch-action:manipulation;-webkit-tap-highlight-color:transparent;
 transition:background .15s ease,border-color .15s ease;
}
.undo-toast-button:focus-visible{outline:2px solid #007f8b;outline-offset:2px}
.undo-toast-button:active{background:#ccebee;border-color:#92ced3}
.undo-toast::before,.undo-toast::after{
 content:"";position:absolute;bottom:3px;left:12px;
 width:calc(100% - 24px);height:3px;border-radius:99px;
 pointer-events:none;
}
.undo-toast::before{background:#e3eff0}
.undo-toast.undo-ticking::after{
 background:linear-gradient(90deg,#00838e,#48b9b4);
 transform-origin:left;
 animation:undo-shrink 8s linear forwards;
}
@keyframes undo-shrink{from{transform:scaleX(1)}to{transform:scaleX(0)}}
.undo-toast.undo-entering{animation:undo-toast-enter .4s cubic-bezier(.22,1,.36,1) both}
.undo-toast.undo-leaving{animation:undo-toast-leave .28s cubic-bezier(.4,0,.75,.25) both;pointer-events:none}
@keyframes undo-toast-enter{
 from{opacity:0;transform:translate3d(-50%,46px,0) scale(.97)}
 to{opacity:1;transform:translate3d(-50%,0,0) scale(1)}
}
@keyframes undo-toast-leave{
 from{opacity:1;transform:translate3d(-50%,0,0) scale(1)}
 to{opacity:0;transform:translate3d(-50%,39px,0) scale(.98)}
}
