/* V34.39 — Lancement PWA : progression sur événements réels et identité sobre.
   Le pourcentage est mis à jour par site-operations.js, pas par animation CSS. */
#iuPwaSplash .iu-splash-title{display:none!important;}
#iuPwaSplash .iu-splash-content{width:min(100%,300px);}
#iuPwaSplash .iu-splash-subtitle{
  margin:0!important;
  color:#60737e!important;
  font-size:12px!important;
  font-weight:700!important;
  line-height:1.45!important;
}
#iuPwaSplash .iu-splash-progress-meta{
  width:190px!important;
  margin:20px 0 9px!important;
}
#iuPwaSplash #iuSplashLoader.iu-splash-loader{
  --iu-splash-progress:0%;
  display:block!important;
  width:190px!important;
  height:12px!important;
  overflow:visible!important;
  border:1px solid #dce7e9!important;
  background:linear-gradient(180deg,#eef4f5,#e7eef0)!important;
  box-shadow:inset 0 1px 2px rgba(48,83,94,.045)!important;
}
#iuPwaSplash #iuSplashLoader.iu-splash-loader::before{
  content:""!important;
  position:absolute!important;
  inset:2px!important;
  z-index:2!important;
  border-radius:999px!important;
  background:repeating-linear-gradient(90deg,transparent 0,transparent calc(25% - 1px),rgba(255,255,255,.48) calc(25% - 1px),rgba(255,255,255,.48) 25%)!important;
  pointer-events:none!important;
}
#iuPwaSplash #iuSplashLoader .iu-splash-loader-fill{
  position:absolute!important;
  top:1px!important;
  bottom:1px!important;
  left:1px!important;
  width:calc(var(--iu-splash-progress) - 2px)!important;
  max-width:calc(100% - 2px)!important;
  min-width:0!important;
  height:auto!important;
  background:linear-gradient(90deg,#77c5b3 0%,#2a8f91 55%,#137e91 100%)!important;
  box-shadow:0 0 8px rgba(42,143,145,.12)!important;
  will-change:auto!important;
}
#iuPwaSplash #iuSplashLoader .iu-splash-loader-cap{
  position:absolute!important;
  top:50%!important;
  left:var(--iu-splash-progress)!important;
  width:12px!important;
  height:12px!important;
  border:2px solid #fff!important;
  border-radius:50%!important;
  background:#278e91!important;
  box-shadow:0 1px 5px rgba(19,114,122,.22)!important;
  transform:translate(-50%,-50%)!important;
  animation:none!important;
  transition:left .32s cubic-bezier(.2,.8,.25,1),opacity .18s ease!important;
}
@media(max-width:380px){
 #iuPwaSplash .iu-splash-progress-meta{width:184px!important;}
 #iuPwaSplash #iuSplashLoader.iu-splash-loader{width:184px!important;}
}
@media(prefers-reduced-motion:reduce){
 #iuPwaSplash #iuSplashLoader .iu-splash-loader-fill,
 #iuPwaSplash #iuSplashLoader .iu-splash-loader-cap{transition:none!important;}
}


/* V34.41 — Concentration : retrouver le défilement naturel d'iOS.
   Aucun espacement artificiel sous la carte de pesée ; les marges
   de scroll ne doivent plus déplacer la page quand le clavier apparaît. */
body.is-focus-mode #grossWeight,
body.is-focus-mode #basketSelect{
  scroll-margin:0!important;
}


/* ================================================================
   V34.44 — AUDIT DE COHÉRENCE VISUELLE
   Ne touche ni au calcul, ni aux résultats, ni au mode Concentration,
   ni aux animations spéciales Événements, PWA ou mise à jour.
   Référentiel : cartes blanches, bord gris bleuté, texte anthracite,
   turquoise seulement sur les actions et états significatifs.
   ================================================================ */
:root{
  --iu-ui-ink:#29343c;
  --iu-ui-muted:#75828b;
  --iu-ui-border:#dfe6e9;
  --iu-ui-surface:#fff;
  --iu-ui-surface-soft:#f7fafb;
  --iu-ui-radius:15px;
  --iu-ui-ease:cubic-bezier(.22,.75,.24,1);
  --iu-ui-speed:560ms;
}
/* Volets secondaires : même famille que les cartes intérieures.
   Pas de modification de hauteur sur les volets principaux préférés. */
body:not(.is-focus-mode) #accountCard .recovery-card,
body:not(.is-focus-mode) #backupCard .backup-advanced,
body:not(.is-focus-mode) #planningAdminCard .planning-import-help {
  box-sizing:border-box!important;
  border:1px solid var(--iu-ui-border)!important;
  border-radius:var(--iu-ui-radius)!important;
  background:linear-gradient(155deg,#fff 0%,#f7fafb 100%)!important;
  box-shadow:inset 0 1px 0 rgba(255,255,255,.95)!important;
  overflow:hidden!important;
}
body:not(.is-focus-mode) #accountCard .recovery-card > summary,
body:not(.is-focus-mode) #backupCard .backup-advanced > summary,
body:not(.is-focus-mode) #planningAdminCard .planning-import-help > summary {
  box-sizing:border-box!important;
  display:flex!important;
  align-items:center!important;
  justify-content:space-between!important;
  gap:10px!important;
  min-height:55px!important;
  padding:13px 15px!important;
  color:var(--iu-ui-ink)!important;
  font-size:12.5px!important;
  font-weight:800!important;
  line-height:1.35!important;
  cursor:pointer;
  background:transparent!important;
  transition:background-color .22s ease!important;
}
body:not(.is-focus-mode) #accountCard .recovery-card > summary:hover,
body:not(.is-focus-mode) #backupCard .backup-advanced > summary:hover,
body:not(.is-focus-mode) #planningAdminCard .planning-import-help > summary:hover{
  background:#f1f6f8!important;
}
#planningAdminCard .planning-import-help > .planning-import-help-body{
  animation:none!important; /* l'animation de hauteur est assurée par JS */
}
#planningAdminCard .planning-import-help > summary svg,
#backupCard .backup-advanced > summary svg,
#accountCard .recovery-card > summary .calc-alerts-chevron{
  width:18px!important;
  height:18px!important;
  flex-shrink:0!important;
  transition:transform var(--iu-ui-speed) var(--iu-ui-ease)!important;
}
#planningAdminCard .planning-import-help.is-detail-closing > summary svg,
#backupCard .backup-advanced.is-detail-closing > summary svg,
#accountCard .recovery-card.is-detail-closing > summary .calc-alerts-chevron{
  transform:rotate(0deg)!important;
}
#planningAdminCard .planning-import-help.is-detail-closing > .planning-import-help-body,
#accountCard .recovery-card.is-detail-closing > .recovery-body{
  opacity:0!important;
  pointer-events:none!important;
}
#planningAdminCard .planning-import-help > .planning-import-help-body,
#accountCard .recovery-card > .recovery-body{
  opacity:1;
  transition:opacity var(--iu-ui-speed) var(--iu-ui-ease)!important;
}
#backupCard .backup-advanced.is-detail-closing > .backup-advanced-body{
  opacity:0!important;
}
/* Rubriques admin et sous-tiroirs Planning : rythme plus uniforme,
   sans remplacer leur moteur d'ouverture existant. */
#planningAdminCard .iu-admin-category > summary,
#planningAdminCard .planning-accordion > .planning-panel-summary{
  font-weight:800!important;
  line-height:1.35!important;
}
#planningAdminCard .iu-admin-category-title small,
#planningAdminCard .iu-update-head p,
#planningAdminCard .site-ops-note,
#planningAdminCard .planning-panel-content > .planning-muted{
  color:var(--iu-ui-muted)!important;
  line-height:1.5!important;
}
#planningAdminCard .iu-admin-category-body > .iu-admin-update,
#planningAdminCard .iu-admin-category-body > .iu-error-panel,
#planningAdminCard .iu-admin-category-body > .site-ops-panel{
  box-shadow:none!important;
}
#planningAdminCard :is(.site-ops-metric,.dashboard-stat,.iu-update-versions > div){
  border-color:var(--iu-ui-border)!important;
  border-radius:13px!important;
}
/* Cartes secondaires de compte, panier, suivi et sauvegarde :
   contours et valeurs dans une même famille, sans recolorer les états. */
body:not(.is-focus-mode) :is(
 #accountCard .account-local-intro,
 #accountCard .account-storage-tile,
 #accountCard .account-dashboard-identity-row,
 #accountCard .dashboard-stat,
 #inventoryCalendar .events-next-card,
 #inventoryCalendar .events-info-box,
 .history-card .history-item,
 .sessions-history-card .v22-session-item,
 .sessions-history-card .v22-stat,
 .basket-card .basket-item,
 .basket-card .basket-form,
 .backup-card .backup-panel
){
  border-color:var(--iu-ui-border)!important;
}
body:not(.is-focus-mode) :is(
 #accountCard .account-storage-tile,
 #accountCard .dashboard-stat,
 .sessions-history-card .v22-stat,
 .basket-card .basket-item
){
  border-radius:13px!important;
}
body:not(.is-focus-mode) :is(
 .history-card .history-item,
 .sessions-history-card .v22-session-item,
 .basket-card .basket-item
){
  min-width:0!important;
}
body:not(.is-focus-mode) :is(
 .history-card .history-item strong,
 .sessions-history-card .v22-session-item summary strong,
 .basket-card .basket-name,
 .backup-card .backup-panel-heading strong
){
  color:var(--iu-ui-ink)!important;
  overflow-wrap:anywhere;
}
body:not(.is-focus-mode) :is(
 .history-card .history-item small,
 .sessions-history-card .v22-session-item summary span,
 .basket-card .basket-order-hint,
 .backup-card .backup-guidance,
 .account-card .account-local-note
){
  color:var(--iu-ui-muted)!important;
  line-height:1.55!important;
}
/* États et pastilles : proportions communes, sans uniformiser les
   couleurs vert/rouge/gris qui indiquent des états différents. */
body:not(.is-focus-mode) :is(
 .session-pill,
 #accountCard .account-summary-status,
 #accountCard .dashboard-cloud-pill,
 #inventoryCalendar .events-countdown,
 #inventoryCalendar .events-state,
 #planningAdminCard .planning-kind
){
  box-sizing:border-box!important;
  border-radius:999px!important;
  line-height:1.2!important;
  font-variant-numeric:tabular-nums!important;
}
/* Boutons secondaires : même prise en main et même retour de focus.
   Ne pas toucher aux boutons de pesée ou aux commandes Concentration. */
body:not(.is-focus-mode) :is(
 .history-card .history-toggle,
 .sessions-history-card .history-toggle,
 .basket-card .small-action,
 .basket-card .move-actions button,
 .backup-card .backup-advanced-body button,
 .backup-card .backup-advanced-body .upload,
 #planningAdminCard .planning-mini-button,
 #planningAdminCard .planning-primary,
 #planningAdminCard .planning-secondary,
 #accountCard .recovery-row button
){
  -webkit-tap-highlight-color:transparent;
  transition:border-color .22s ease,background-color .22s ease,
             box-shadow .22s ease,opacity .22s ease,transform .18s ease!important;
}
body:not(.is-focus-mode) :is(
 .history-card .history-toggle,
 .sessions-history-card .history-toggle,
 .basket-card .small-action,
 .basket-card .move-actions button,
 .backup-card .backup-advanced-body button,
 .backup-card .backup-advanced-body .upload,
 #planningAdminCard .planning-mini-button,
 #accountCard .recovery-row button
):active:not(:disabled){
  transform:scale(.985)!important;
}
/* Un repère d'accessibilité identique partout, uniquement au clavier.
   Les taps iPhone n'affichent pas de contour parasite. */
body:not(.is-focus-mode) :is(
 .app > details.fold-card > summary,
 #inventoryCalendar .events-disclosure > summary,
 #accountCard .recovery-card > summary,
 #backupCard .backup-advanced > summary,
 #planningAdminCard .iu-admin-category > summary,
 #planningAdminCard .planning-accordion > summary,
 #planningAdminCard .planning-import-help > summary,
 .sessions-history-card .v22-session-item > summary,
 button,
 .upload
):focus-visible{
  outline:2px solid #4a9ba6!important;
  outline-offset:3px!important;
}
/* Les dialogs partagent un cadre et des titres lisibles ; le positionnement
   et leurs animations d'entrée/sortie restent spécifiques à chaque usage. */
#importChoiceDialog,
#otherTabDialog,
#planningConfirmDialog,
#eventsInstallDialog{
  border-color:var(--iu-ui-border)!important;
  border-radius:20px!important;
  box-shadow:0 20px 58px rgba(28,50,64,.16)!important;
}
#importChoiceDialog h2,
#otherTabDialog h2,
#planningConfirmDialog h3,
#eventsInstallDialog .events-install-dialog-head strong{
  color:var(--iu-ui-ink)!important;
  line-height:1.35!important;
  letter-spacing:-.2px!important;
}
#importChoiceDialog p,
#otherTabDialog p,
#planningConfirmDialog p{
  line-height:1.55!important;
}
/* Assurer la lisibilité sur petit iPhone, sans élargir la page. */
@media(max-width:380px){
 #planningAdminCard .iu-admin-category-body,
 #planningAdminCard .planning-panel-content,
 #accountCard .account-body,
 .backup-card .backup-body{
  min-width:0!important;
 }
 body:not(.is-focus-mode) #accountCard .recovery-card > summary,
 body:not(.is-focus-mode) #backupCard .backup-advanced > summary,
 body:not(.is-focus-mode) #planningAdminCard .planning-import-help > summary{
  min-height:51px!important;
  padding:12px!important;
 }
}
@media(prefers-reduced-motion:reduce){
 #planningAdminCard .planning-import-help > .planning-import-help-body,
 #accountCard .recovery-card > .recovery-body,
 #planningAdminCard .planning-import-help > summary svg,
 #backupCard .backup-advanced > summary svg,
 #accountCard .recovery-card > summary .calc-alerts-chevron{
  transition:none!important;
  animation:none!important;
 }
}


/* ====================================================================
   V34.45 — CONTEXTES MONOCHROMES ET BANDEAU
   Le mode Concentration, le calcul, le SW et les animations ne changent pas.
   ==================================================================== */

/* Les trois compteurs sont des nombres, pas des états : sans point/pulse. */
body:not(.is-focus-mode) .app > details.card.fold-card .fold-trailing :is(#historyCount,#sessionsCount,#basketCount).count.session-pill {
  display:inline-flex!important;
  align-items:center!important;
  justify-content:center!important;
  min-height:32px!important;
  padding:8px 12px!important;
  border:1px solid #d9e1e5!important;
  border-radius:999px!important;
  background:#edf0f1!important;
  color:#5e6370!important;
  box-shadow:inset 0 1px 0 rgba(255,255,255,.9)!important;
  white-space:nowrap!important;
}
body:not(.is-focus-mode) .app > details.card.fold-card .fold-trailing :is(#historyCount,#sessionsCount,#basketCount).count.session-pill::before,
body:not(.is-focus-mode) .app > details.card.fold-card .fold-trailing :is(#historyCount,#sessionsCount,#basketCount).count.session-pill::after {
  content:none!important;
  display:none!important;
  animation:none!important;
}

/* Banderole : un soupçon plus haute, coins bas moins carrés.
   Raccourcir l'ombre sous le bouton sans changer la taille de ce bouton. */
.app > .intro {
  border-radius:0 0 11px 11px!important;
  padding-top:39px!important;
  padding-bottom:31px!important;
  box-shadow:0 13px 22px -10px rgba(48,88,82,.12),
             0 24px 39px -17px rgba(49,87,83,.09)!important;
}
.app > .intro .intro-jump {
  box-shadow:inset 0 1px 0 rgba(255,255,255,.9),
             0 5px 11px -6px rgba(17,50,46,.13)!important;
}
.app > .intro .intro-jump:hover:not(:disabled){
  box-shadow:inset 0 1px 0 #fff,
             0 6px 13px -7px rgba(17,50,46,.15)!important;
}
.app > .intro .intro-jump:disabled{
  opacity:.66!important;
  cursor:default!important;
  box-shadow:inset 0 1px 0 rgba(255,255,255,.9)!important;
}
@media(max-width:600px){
  .app > .intro{padding-top:35px!important;}
}
@media(max-width:380px){
  .app > .intro{padding-top:34px!important;padding-bottom:28px!important;}
}

/* Sauvegarde : finition gris/blanc anthracite identique au registre Admin. */
body:not(.is-focus-mode) .app > #backupCard.backup-card {
  border-color:#dce1e5!important;
  background:linear-gradient(155deg,#fff 0%,#fafbfc 60%,#f4f5f7 100%)!important;
}
body:not(.is-focus-mode) #backupCard .backup-panel,
body:not(.is-focus-mode) #backupCard .backup-summary,
body:not(.is-focus-mode) #backupCard .backup-advanced {
  border-color:#dce1e5!important;
  background:linear-gradient(155deg,#fff 0%,#f7f8f9 100%)!important;
  box-shadow:inset 0 1px 0 #fff!important;
}
body:not(.is-focus-mode) #backupCard .backup-panel-heading{
  border-bottom-color:#e1e5e8!important;
}
body:not(.is-focus-mode) #backupCard .backup-panel-icon{
  border:1px solid #dce1e5!important;
  color:#56616b!important;
  background:linear-gradient(145deg,#fff,#eef0f2)!important;
  box-shadow:inset 0 1px 0 #fff!important;
}
body:not(.is-focus-mode) #backupCard :is(.backup-panel-heading strong,.backup-advanced > summary){
  color:#2b333a!important;
}
body:not(.is-focus-mode) #backupCard :is(.backup-panel-heading span,.backup-summary,.backup-last,.backup-guidance,.backup-advanced-body > p,.backup-status){
  color:#707a83!important;
}
body:not(.is-focus-mode) #backupCard .backup-main-btn{
  border:1px solid #343b43!important;
  background:linear-gradient(155deg,#424a52,#2d343b)!important;
  color:#fff!important;
  box-shadow:inset 0 1px 0 rgba(255,255,255,.13),0 3px 10px rgba(26,36,44,.09)!important;
}
body:not(.is-focus-mode) #backupCard .backup-main-btn:hover:not(:disabled){
  background:linear-gradient(155deg,#495159,#343b43)!important;
}
body:not(.is-focus-mode) #backupCard :is(.backup-restore-btn,.backup-advanced-body > button,.backup-advanced-body > label.outline-btn){
  border:1px solid #d5dbe0!important;
  background:linear-gradient(155deg,#fff,#eff1f3)!important;
  color:#39434c!important;
  box-shadow:inset 0 1px 0 #fff!important;
}
body:not(.is-focus-mode) #backupCard :is(.backup-restore-btn,.backup-advanced-body > button,.backup-advanced-body > label.outline-btn):hover{
  background:linear-gradient(155deg,#fff,#e9ecef)!important;
}
body:not(.is-focus-mode) #backupCard .backup-advanced-body{
  border-top-color:#e0e4e8!important;
}

/* Pop-ups et notifications : fonds blanc/gris, relief discret, symboles
   anthracite. Les textes et actions conservent leur signification. */
.toast-stack > .undo-toast,
.toast-stack > .offline-indicator,
.undo-toast,
.offline-indicator {
  border:1px solid #dce2e6!important;
  border-radius:18px!important;
  background:linear-gradient(155deg,#fff 0%,#f4f6f8 100%)!important;
  color:#29343c!important;
  box-shadow:0 13px 32px rgba(38,50,61,.13),inset 0 1px 0 #fff!important;
  text-shadow:none!important;
}
.toast-stack > .undo-toast.toast-warning,
.undo-toast.toast-warning{
  border-color:#cfd6dc!important;
  background:linear-gradient(155deg,#fff,#f3f5f6)!important;
}
.toast-stack > .undo-toast .undo-toast-symbol,
.toast-stack > .offline-indicator .offline-symbol,
.undo-toast .undo-toast-symbol,
.offline-indicator .offline-symbol{
  border:1px solid #d4dce1!important;
  background:#eceff1!important;
  color:#46525b!important;
  box-shadow:none!important;
}
.offline-indicator .offline-symbol img{
  filter:grayscale(1)!important;
  opacity:.8!important;
}
.toast-stack :is(.undo-toast-message,.offline-copy strong),
.undo-toast .undo-toast-message,
.offline-indicator .offline-copy strong{
  color:#29343c!important;
  text-shadow:none!important;
}
.toast-stack .offline-copy > span,
.offline-indicator .offline-copy > span{
  color:#737e87!important;
  text-shadow:none!important;
}
.toast-stack .undo-toast-button,
.undo-toast .undo-toast-button{
  border:1px solid #cbd3d9!important;
  background:linear-gradient(155deg,#f7f8f9,#e9edf0)!important;
  color:#343f48!important;
  box-shadow:none!important;
}
.toast-stack .toast-close,
.toast-stack .offline-dismiss,
.undo-toast .toast-close,
.offline-indicator .offline-dismiss{
  color:#616d76!important;
  border-color:transparent!important;
  background:transparent!important;
  box-shadow:none!important;
}
.toast-stack :is(.toast-close,.offline-dismiss):hover,
.toast-stack .undo-toast-button:hover:not(:disabled){
  background:#edf0f2!important;
}
.undo-toast.undo-ticking::before,
.undo-toast.undo-ticking::after{
  background:#7f8b95!important;
}

/* Dialogue de fin et d'annulation de planning / restauration / tutoriel. */
#importChoiceDialog,
#otherTabDialog,
#planningConfirmDialog,
#eventsInstallDialog,
.account-modal .account-dialog {
  border:1px solid #dce2e6!important;
  background:linear-gradient(155deg,#fff,#f6f7f8)!important;
  color:#29343c!important;
  box-shadow:0 20px 55px rgba(32,43,52,.17)!important;
}
:is(#importChoiceDialog,#otherTabDialog,#planningConfirmDialog,#eventsInstallDialog) :is(h2,h3,p,li,strong){
  color:#303a43!important;
}
#planningConfirmDialog .planning-confirm-symbol,
#eventsInstallDialog .events-install-dialog-symbol{
  border:1px solid #dce2e6!important;
  background:#eceff1!important;
  color:#505b65!important;
}
#planningConfirmDialog :is(.planning-primary,.planning-secondary),
:is(#importChoiceDialog,#otherTabDialog) :is(.primary-btn,.outline-btn,.ghost-btn,button){
  border:1px solid #cfd6dc!important;
  background:linear-gradient(155deg,#fff,#e9edf0)!important;
  color:#35414b!important;
  box-shadow:none!important;
}
#planningConfirmDialog .planning-primary,
:is(#importChoiceDialog,#otherTabDialog) .primary-btn{
  border-color:#3d464d!important;
  background:linear-gradient(155deg,#484f57,#30363c)!important;
