}
#eventsInstallDialog .events-install-success{
  border-top-color:#dce2e6!important;
  color:#49555d!important;
  background:transparent!important;
}
#eventsInstallDialog .events-inline-icon:not(img){
  background-color:transparent!important;
  border-color:transparent!important;
}
body.is-focus-mode #focusToolbar #focusConfirm.focus-confirm{
  background:linear-gradient(155deg,#fff,#f3f5f6)!important;
  border-color:#dce2e6!important;
}
body.is-focus-mode #focusToolbar #focusConfirm :is(#focusConfirmStop,#focusCancelStop){
  border:1px solid #d6dce1!important;
  background:linear-gradient(155deg,#fff,#edeff1)!important;
  color:#3e4750!important;
}
body.is-focus-mode #focusToolbar #focusConfirm #focusConfirmStop{
  border-color:#3c444c!important;
  background:linear-gradient(155deg,#494f57,#333a41)!important;
  color:#fff!important;
