 border:1px solid rgba(44,141,191,.44)!important;
 box-shadow:inset 0 1px 0 rgba(255,255,255,.88),
            0 5px 15px rgba(31,52,65,.075)!important;
}
body:not(.is-focus-mode) .app > .session-card.card #sessionMessage.v22-message.is-complete:not(:empty)::after{
 background:linear-gradient(180deg,rgba(44,141,191,.66),rgba(44,141,191,.16))!important;
 opacity:.72!important;
}
body:not(.is-focus-mode) .app > .session-card.card #sessionMessage .session-complete-title{
 color:#29343d!important;
 text-shadow:none!important;
}
body:not(.is-focus-mode) .app > .session-card.card #sessionMessage .session-complete-detail{
